(function(){"use strict";importScripts("https://cdn.jsdelivr.net/npm/hash-wasm@4.11.0/dist/sha256.umd.min.js"),self.onmessage=async n=>{const e=n.data.file,r=10*1024*1024,a=Math.ceil(e.size/r);try{const s=await hashwasm.createSHA256();s.init();for(let t=0;t<a;t++){const o=t*r,c=Math.min(o+r,e.size),h=await e.slice(o,c).arrayBuffer();s.update(new Uint8Array(h)),self.postMessage({type:"progress",progress:Math.round((t+1)/a*100)})}const i=s.digest();self.postMessage({type:"complete",hash:i})}catch(s){self.postMessage({type:"error",error:String(s)})}}})();
